CREATE POLICY "Users read own ad image files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'ad-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users upload own ad image files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'ad-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users delete own ad image files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'ad-images' AND auth.uid()::text = (storage.foldername(name))[1]);